function I({registerIndicator:F,sourceValues:N,nulls:x}){F({id:"oa-hema",name:"Hull Exponential Moving Average (HEMA)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"hema",type:"line",title:"HEMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(p,d){const A=Math.max(1,Math.floor(Number(d.period)||10)),H=N(p,d.source??"close"),f=p.length,y=A,r=3/(2*y-1),R=-Math.log(1-r),t=Math.log(2)/(1+Math.log(2)),b=1-Math.exp(-R/t),i=2/(Math.sqrt(y)/2+1),k=1-r,E=1-b,v=1-i;let w=!0,m=1,S=1,M=1,a=0,o=0,e=0;const g=new Array(f).fill(NaN);for(let l=0;l<f;l++){const h=H[l];if(!Number.isFinite(h))continue;a=r*(h-a)+a,o=b*(h-o)+o;let n,s,c;if(w){m*=k,S*=E,M*=v,n=1/(1-m)*a,s=1/(1-S)*o;const u=s/(1-t)-t*n/(1-t);e=i*(u-e)+e,c=1/(1-M)*e,w=m>1e-10}else{n=a,s=o;const u=s/(1-t)-t*n/(1-t);e=i*(u-e)+e,c=e}Number.isFinite(c)&&(g[l]=c)}return{hema:x(g)}}})}export{I as default};
